/**
 * Whole-package import handling.
 *
 * The converter rewrites one plugin factory into a V2 module. Everything else in the
 * package still imports the V1 authoring package (`tool`, `Plugin`, `ToolContext`, ...).
 * Those are authoring-time helpers: they shape values the V2 runtime never imports
 * directly. A generated compatibility module keeps the remaining files compiling and
 * removes the V1 package from the runtime graph.
 */
import fs from "node:fs"
import path from "node:path"
import type { Diagnostic } from "../core/diagnostics"

const V1 = "@opencode-ai/plugin"
const SOURCE = /\.(?:[cm]?tsx?)$/
const SKIP_DIRS = new Set(["node_modules", "dist", ".git", "coverage", ".turbo", ".migrate"])

export const SHIM_FILE = "__opencode_v1_shim.ts"

const IMPORT_PATTERN =
  /import\s+(type\s+)?([^;'"]*?)\s*from\s*(['"])(@opencode-ai\/plugin(?:\/[^'"]*)?)\3/g
const HAS_IMPORT = /import\s+(?:type\s+)?[^;'"]*?\s*from\s*['"]@opencode-ai\/plugin/

const SHIM_BASE = `
/**
 * V1 authoring-compatibility shim generated by opencode-plugin-migrate.
 *
 * \`tool()\` keeps the original Zod shape so a tool registration can convert it with
 * \`z.toJSONSchema()\`; the V2 runtime never imports the V1 package directly.
 */
import { z } from "zod"

export type PluginInput = {
  client: any
  project: any
  directory: string
  worktree: string
  serverUrl: URL
  $: any
  experimental_workspace: { register(type: string, adapter: any): void }
}
export type PluginOptions = Record<string, unknown>
export type Hooks = Record<string, any>
export type Plugin = (input: PluginInput, options?: PluginOptions) => Promise<Hooks>
export type PluginModule = { id?: string; server: Plugin; tui?: never }
export type ToolContext = {
  sessionID: string
  messageID: string
  agent: string
  directory: string
  worktree: string
  abort: AbortSignal
  metadata(input: { title?: string; metadata?: Record<string, any> }): void
  ask(input: { permission: string; patterns: string[]; always: string[]; metadata: Record<string, any> }): Promise<void>
}
export type ToolAttachment = { type: "file"; mime: string; url: string; filename?: string }
export type ToolResult =
  | string
  | {
      title?: string
      output: string
      metadata?: Record<string, any>
      attachments?: ToolAttachment[]
    }
export type ToolDefinition = {
  description: string
  args: any
  execute(args: any, context: ToolContext): Promise<ToolResult>
}
export type Config = any
export type AuthHook = any
export type ProviderHook = any
export type ProviderContext = any
export type AuthOAuthResult = any
export type Permission = any

export const tool: {
  (definition: ToolDefinition): ToolDefinition
  schema: typeof z
} = Object.assign((definition: ToolDefinition) => definition, { schema: z })

export default tool
`

const SHIM_BASE_NAMES = new Set([
  "PluginInput",
  "PluginOptions",
  "Hooks",
  "Plugin",
  "PluginModule",
  "ToolContext",
  "ToolAttachment",
  "ToolResult",
  "ToolDefinition",
  "Config",
  "AuthHook",
  "ProviderHook",
  "ProviderContext",
  "AuthOAuthResult",
  "Permission",
  "tool",
])

export interface V1ImportNames {
  /** Names imported in value position (runtime). `tool` is the only common one. */
  readonly values: Set<string>
  /** Names imported in type position. */
  readonly types: Set<string>
}

export interface V1ImportSite {
  readonly file: string
  /** `@opencode-ai/plugin` or a subpath such as `@opencode-ai/plugin/tui`. */
  readonly specifier: string
  readonly names: V1ImportNames
  readonly namespace: boolean
  readonly defaultImport: boolean
  readonly subpath: boolean
}

export interface RewriteResult {
  /** Files whose V1 imports were redirected to the shim. */
  readonly rewritten: string[]
  /** Files that still contain a V1 import the shim cannot represent. */
  readonly remaining: string[]
  readonly shim?: string
  readonly diagnostics: Diagnostic[]
}

function walk(dir: string, found: string[] = []): string[] {
  if (!fs.existsSync(dir)) return found
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (SKIP_DIRS.has(entry.name)) continue
    const full = path.join(dir, entry.name)
    if (entry.isDirectory()) walk(full, found)
    else if (SOURCE.test(entry.name) && !entry.name.endsWith(".d.ts")) found.push(full)
  }
  return found
}

function parseClause(clause: string, typeOnly: boolean) {
  const values = new Set<string>()
  const types = new Set<string>()
  let namespace = false
  let defaultImport = false
  const trimmed = clause.trim().replace(/,$/, "")

  if (trimmed.startsWith("*")) {
    namespace = true
    return { values, types, namespace, defaultImport }
  }

  const brace = /\{([\s\S]*)\}/.exec(trimmed)
  if (brace) {
    for (const raw of (brace[1] ?? "").split(",")) {
      const part = raw.trim()
      if (!part) continue
      const isType = typeOnly || /^type\s+/.test(part)
      const name = part
        .replace(/^type\s+/, "")
        .split(/\s+as\s+/)[0]
        ?.trim()
      if (!name) continue
      if (isType) types.add(name)
      else values.add(name)
    }
    const before = trimmed.slice(0, brace.index).replace(/,\s*$/, "").trim()
    if (before) defaultImport = true
    return { values, types, namespace, defaultImport }
  }

  if (trimmed) defaultImport = true
  return { values, types, namespace, defaultImport }
}

export function findV1Imports(dir: string): V1ImportSite[] {
  const sites: V1ImportSite[] = []
  for (const file of walk(dir)) {
    const text = fs.readFileSync(file, "utf8")
    if (!text.includes(V1)) continue
    for (const match of text.matchAll(IMPORT_PATTERN)) {
      const specifier = match[4] ?? V1
      const parsed = parseClause(match[2] ?? "", Boolean(match[1]))
      sites.push({
        file,
        specifier,
        names: { values: parsed.values, types: parsed.types },
        namespace: parsed.namespace,
        defaultImport: parsed.defaultImport,
        subpath: specifier !== V1,
      })
    }
  }
  return sites
}

export function countV1ImportFiles(dir: string): number {
  return new Set(findV1Imports(dir).map((site) => site.file)).size
}

function shimSpecifier(fromFile: string, root: string): string {
  const shim = path.join(root, SHIM_FILE)
  let relative = path.relative(path.dirname(fromFile), shim).split(path.sep).join("/")
  relative = relative.replace(/\.[cm]?tsx?$/, "")
  return relative.startsWith(".") ? relative : `./${relative}`
}

function renderShim(values: Set<string>, types: Set<string>): string {
  const lines = [SHIM_BASE.trimEnd(), ""]
  const extraValues = [...values].filter((name) => !SHIM_BASE_NAMES.has(name))
  const extraTypes = [...types].filter((name) => !SHIM_BASE_NAMES.has(name))
  // A name imported as both a value and a type can only be exported once.
  const both = extraValues.filter((name) => extraTypes.includes(name))
  for (const name of extraValues.sort()) {
    if (both.includes(name)) continue
    lines.push(`export const ${name}: any = undefined`)
  }
  for (const name of extraTypes.sort()) {
    if (both.includes(name)) continue
    lines.push(`export type ${name} = any`)
  }
  if (both.length) {
    lines.push(
      "",
      `// Imported as both value and type; treated as a type: ${both.sort().join(", ")}`,
    )
    for (const name of both.sort()) lines.push(`export type ${name} = any`)
  }
  return `${lines.join("\n")}\n`
}

/**
 * Replace V1 authoring imports in every file of the copied project with the generated
 * shim, except files already emitted by the converter. Files using a shape the shim
 * cannot represent (namespace/default imports, runtime subpath imports) are left alone
 * and reported, so the manifest keeps the V1 dependency.
 */
export function rewriteV1Imports(root: string, skip: string[] = []): RewriteResult {
  const skipped = new Set(skip.map((file) => path.resolve(file)))
  const sites = findV1Imports(root).filter((site) => !skipped.has(path.resolve(site.file)))
  const values = new Set<string>()
  const types = new Set<string>()
  const rewritten: string[] = []
  const remaining: string[] = []
  const diagnostics: Diagnostic[] = []

  const byFile = new Map<string, V1ImportSite[]>()
  for (const site of sites) {
    const list = byFile.get(site.file) ?? []
    list.push(site)
    byFile.set(site.file, list)
  }

  for (const [file, imports] of byFile) {
    const unsupported = imports.filter(
      (site) =>
        site.namespace ||
        site.defaultImport ||
        // Runtime values from a subpath are a different package surface (TUI, ...).
        (site.subpath && site.names.values.size > 0),
    )
    if (unsupported.length) {
      remaining.push(file)
      diagnostics.push({
        code: "imports/unsupported",
        severity: "warning",
        message: `${path.relative(root, file)} imports a V1 shape the shim cannot represent (namespace/default import or a runtime subpath); it was left untouched, so the V1 package must stay installed.`,
      })
      continue
    }

    const specifier = shimSpecifier(file, root)
    let text = fs.readFileSync(file, "utf8")
    for (const site of imports) {
      for (const name of site.names.values) values.add(name)
      for (const name of site.names.types) types.add(name)
    }
    text = text.replace(
      /(['"])@opencode-ai\/plugin(?:\/[^'"]*)?\1/g,
      (_match, quote: string) => `${quote}${specifier}${quote}`,
    )
    if (HAS_IMPORT.test(text)) {
      remaining.push(file)
      diagnostics.push({
        code: "imports/unmatched",
        severity: "warning",
        message: `${path.relative(root, file)} still contains a V1 import after rewriting.`,
      })
      continue
    }
    fs.writeFileSync(file, text)
    rewritten.push(file)
  }

  let shim: string | undefined
  if (rewritten.length) {
    shim = path.join(root, SHIM_FILE)
    fs.writeFileSync(shim, renderShim(values, types))
    diagnostics.push({
      code: "imports/shim",
      severity: "info",
      message: `${rewritten.length} file(s) now import the generated V1 compatibility shim (${SHIM_FILE}).`,
    })
  }

  return { rewritten, remaining, ...(shim ? { shim } : {}), diagnostics }
}
